    "fault_code_1309": {
      "name_en": "Fault code",
      "category": "chiller",
      "address": 1309,
      "address_hex": "0x051D",
      "data_type": "U16",
      "access": "R",
      "notes":
          "bit 0 -1# Discharge temp sensor failure , bit 1 -1# Condensation temp senor failure ,bit 2 - 2# Discharge temp sensor failure , bit 3 -2# Condensation temp senor failure , bit 4 -Inlet water temp sensor failure , bit 5 - Outlet water temp sensor failure , bit 6 - Ambient temp sensor failure , bit 7 - Abnormal power down alarm , bit 8 - 1# High press sensor failure , bit 9 - 2# High press sensor failure , bit 10 - Water tank water level low , bit 11 - Return water pressure sensor failure , bit 12 - Outlet water pressure sensor failure",
    },
    "fault_code_1310": {
      "name_en": "Fault code",
      "category": "chiller",
      "address": 1310,
      "address_hex": "0x051E",
      "data_type": "U16",
      "access": "R",
    },
    "fault_code_1311": {
      "name_en": "Fault code",
      "category": "chiller",
      "address": 1311,
      "address_hex": "0x051F",
      "data_type": "U16",
      "access": "R",
      "notes":
          "bit 0 -1# High press lock , bit 1 - 1# Discharge over temp lock , bit 2 -1# System low press alarm lock , bit 3 - 1# Low press sensor failure , bit 4  - 1# Evap outlet temp senor failure , bit 5 -  1# Comp freq converter failure ,bit 6 - 1# Comp freq converter commun failure , bit 7 - 1# Outdoor fan freq converter failure , bit 8 - 1# Outdoor fan freq converter commu failure , bit 9 -2# High press lock , bit 10 - 2# Discharge over temp lock , bit 11 - 2# System low press alarm lock , bit 12 - 2# Low press sensor failure , bit 13 - 2# Evap outlet temp senor failure , bit 14 - 2# Comp freq converter failure , bit 15 - 2# Comp freq converter commun failure",
    },
    "fault_code_1312": {
      "name_en": "Fault code",
      "category": "chiller",
      "address": 1312,
      "address_hex": "0x0520",
      "data_type": "U16",
      "access": "R",
      "notes":
          "bit 0 -Expansion module commun failure , bit 1 - 2# Outdoor fan freq converter failure , bit 2 - 2# Outdoor fan freq converter commu failure , bit 3 - Water pump low press diff , bit 4 -Inlet water temp sensor failure & Outlet water temp sensor failure , bit 5 - Power supply failure , bit 6 - Inlet water press sensor failure & Outlet water press sensor failure , bit 8 - 1# Circulating water pump freq converter failure , bit 9 - 1# Circulating water pump freq converter commun failure , bit 10 - 1# Electrical heater failure lock , bit 11 - Outlet water high temp , bit 12 - Outlet water low temp , bit 13 - 1# Circulating water pump superheat protection alarm lock , bit 14 - 2# Circulating water pump superheat protection alarm lock , bit 15 -1# Circulating water pump overload protection lock",
    },
    "fault_code_1313": {
      "name_en": "Fault code",
      "category": "chiller",
      "address": 1313,
      "address_hex": "0x0521",
      "data_type": "U16",
      "access": "R",
      "notes":
          "bit 0 - 2# Circulating water pump overload protection lock , bit 1 - 2# Circulating water pump freq converter failure , bit 2 - 2# Circulating water pump freq converter commun failure , bit 3 - 2# Electrical heater failure lock , bit 4 - APF failure , bit 5 - DC_DC1 module failure , bit 6 - DC_DC2 module failure",
    },
    "fault_code_1314": {
