    "status_word": {
      "name_en": "PCS status word",
      "category": "status",
      "address": 2057,
      "address_hex": "0x0809",
      "data_type": "U16",
      "bitfields": [
        {
          "bit": 0,
          "key": "dcpre_charge",
          "name_en": "DCPre-Charge",
          "value_text": "\"0:Disconnected\"\"1:Connected\"",
        },
        {
          "bit": 1,
          "key": "acsoft_start",
          "name_en": "ACSoftStart",
          "value_text": "\"0:Disconnected\"\"1:Connected\"",
        },
        {
          "bit": 2,
          "key": "dcrelay",
          "name_en": "DCRelay",
          "value_text": "\"0:Disconnected\"\"1:Connected\"",
        },
        {
          "bit": 3,
          "key": "acrelay",
          "name_en": "ACRelay",
          "value_text": "\"0:Disconnected\"\"1:Connected\"",
        },
        {
          "bit": 4,
          "key": "off_grid",
          "name_en": "Off-grid",
          "value_text": "\"0:On-Grid\"\"1:Off-Grid\"",
        },
        {
          "bit": 5,
          "key": "chargeand_discharge",
          "name_en": "ChargeandDischarge",
          "value_text": "\"0:Discharging\"\"1:Charging\"",
        },
        {
          "bit": 6,
          "key": "operation_status",
          "name_en": "OperationStatus",
          "value_text": "\"0:Stop\"\"1:Run\"",
        },
        {
          "bit": 7,
          "key": "faultstatus",
          "name_en": "Faultstatus",
          "value_text": "\"0:No\"\"1:Yes\"",
        },
        {
          "bit": 8,
          "key": "master_slavemachine",
          "name_en": "Master-slavemachine",
          "value_text": "\"0:Slavemachine\"\"1:Mastermachine\"",
        },
        {
          "bit": 9,
          "key": "master_slavecabinet",
          "name_en": "Master-slavecabinet",
          "value_text": "\"0:Slavecabinet\"1:Mastercabinet\"",
        },
        {
          "bit": 10,
          "key": "standby",
          "name_en": "Standby",
          "value_text": "\"0:No\"\"1:Standby\"",
        },
        {
          "bit": 11,
          "key": "shutdown",
          "name_en": "Shutdown",
          "value_text": "\"0:No\"\"1:Shutdown\"",
        },
        {
          "bit": 12,
          "key": "epo",
          "name_en": "EPO",
          "value_text": "\"0:No\"\"1:Emergencystop\"",
        },
        {
          "bit": 15,
          "key": "parameterinitialization",
          "name_en": "Parameterinitialization",
          "value_text": "\"0:Notcompleted\"\"1:Completed\"",
        },
      ],
      "access": "R",
    },
